import { useState } from 'react';

const CHIP_LABELS = ['All', 'Active', 'Archived', 'Starred'] as const;
type ChipLabel = (typeof CHIP_LABELS)[number];

// Owns only visual pressed state; grid filtering is wired by the consumer.
const chipStyles = `
@layer components {
  .chip-filter-bar {
    display: flex;
    gap: var(--shelf-chip-gap);
    padding: var(--shelf-chip-padding-block) 0;
  }

  .chip-filter-btn {
    appearance: none;
    background-color: var(--shelf-chip-bgColor-default);
    color: var(--shelf-chip-fgColor-default);
    border: 1px solid var(--shelf-chip-borderColor-default);
    border-radius: var(--shelf-chip-radius);
    padding: var(--shelf-chip-padding-block) var(--shelf-chip-padding-inline);
    cursor: pointer;
    font-size: var(--shelf-chip-font-size);
    font-weight: var(--shelf-chip-font-weight);
  }

  .chip-filter-btn[aria-pressed="true"] {
    background-color: var(--shelf-chip-bgColor-pressed);
    color: var(--shelf-chip-fgColor-pressed);
    border-color: var(--shelf-chip-borderColor-pressed);
  }

  .chip-filter-btn:hover:not([aria-pressed="true"]) {
    background-color: var(--shelf-chip-bgColor-hover);
  }

  .chip-filter-btn:focus-visible {
    outline: var(--shelf-focusRing);
    outline-offset: var(--shelf-focusRing-offset);
  }
}
`;

export function ChipFilter(): JSX.Element {
  const [activeChip, setActiveChip] = useState<ChipLabel>('All');

  return (
    <>
      <style>{chipStyles}</style>
      <div role="group" aria-label="Filter chips" className="chip-filter-bar">
        {CHIP_LABELS.map((label) => (
          <button
            key={label}
            type="button"
            className="chip-filter-btn"
            aria-pressed={activeChip === label}
            onClick={() => setActiveChip(label)}
          >
            {label}
          </button>
        ))}
      </div>
    </>
  );
}
